/*
 * A332266  Irregular triangle read by rows: T(n,k), n >= 1, k >= 1, in which
 *          column k lists successive blocks of k consecutive integers that
 *          differ by 2, where the m-th block starts with m, m >= 1, and the
 *          first element of column k is in row k^2.
 * https://oeis.org/A332266
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) generated by the irregular triangle read by rows. Column k
 *            (k≥1) lists successive blocks of k integers differing by 2. The
 *            m‑th block starts with m. The first element of column k occurs
 *            in row k². For n≥k² the entry is T(n,k) = 1 + ⌊(n−k²)/k⌋ +
 *            2·((n−k²) mod k)
 * Range:     u8 n <= 85, u16 n <= 85, u32 n <= 85, u64 n <= 85, u128 n <= 85,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* Static cache for memoized results */
static seq_t *cache = NULL;
static idx_t  cache_size = 0;   /* number of terms stored */
static idx_t  cache_cap  = 0;   /* allocated capacity */
static idx_t  next_row   = 1;   /* next row to process */

/* Grow the cache to at least new_cap elements */
static void grow_cache(idx_t new_cap)
{
    if (cache_cap >= new_cap)
        return;
    size_t cap = (cache_cap > 0) ? cache_cap * 2 : 16;
    while (cap < (size_t)new_cap)
        cap *= 2;
    seq_t *tmp = (seq_t *)realloc(cache, cap * sizeof(seq_t));
    cache = tmp;
    cache_cap = (idx_t)cap;
}

/* Ensure that terms up to index n (1‑based) are computed */
static void ensure_cache(idx_t n)
{
    while (cache_size < n) {
        idx_t r = next_row;
        /* find kmax = floor(sqrt(r)) */
        idx_t kmax = 0;
        while ((kmax + 1) * (kmax + 1) <= r)
            ++kmax;
        for (idx_t k = 1; k <= kmax; ++k) {
            idx_t delta = r - k * k;
            idx_t b   = delta / k;
            idx_t pos = delta % k;
            seq_t val = (seq_t)(1 + b + 2 * pos);
            grow_cache(cache_size + 1);
            cache[cache_size++] = val;
        }
        ++next_row;
    }
}

seq_t a(idx_t n)
{
    if (n == 0)         /* safety for non‑positive indices */
        return (seq_t)0;
    ensure_cache(n);
    return cache[n - 1];
}
